<?php
require_once "../config/config.php"; adminLogin();
$bulan=(int)($_GET['bulan']??date('m')); $tahun=(int)($_GET['tahun']??date('Y'));
if($bulan<1||$bulan>12||$tahun<2000||$tahun>2100){http_response_code(400);exit('Periode laporan tidak valid.');}
$awal=sprintf('%04d-%02d-01',$tahun,$bulan); $akhir=date('Y-m-d',strtotime($awal.' +1 month')); $params=[$awal,$akhir];
$q=$pdo->prepare('SELECT COALESCE(SUM(jumlah),0) FROM pendapatan WHERE tanggal>=? AND tanggal<?');$q->execute($params);$pendapatan=$q->fetchColumn();
$q=$pdo->prepare('SELECT COALESCE(SUM(jumlah),0) FROM pengeluaran WHERE tanggal>=? AND tanggal<?');$q->execute($params);$pengeluaran=$q->fetchColumn();$saldo=$pendapatan-$pengeluaran;
$q=$pdo->prepare('SELECT * FROM pendapatan WHERE tanggal>=? AND tanggal<? ORDER BY tanggal DESC,id DESC');$q->execute($params);$dataPendapatan=$q->fetchAll();
$q=$pdo->prepare('SELECT * FROM pengeluaran WHERE tanggal>=? AND tanggal<? ORDER BY tanggal DESC,id DESC');$q->execute($params);$dataPengeluaran=$q->fetchAll();
$q=$pdo->prepare('SELECT kategori,SUM(jumlah) total,COUNT(*) jumlah_transaksi FROM pendapatan WHERE tanggal>=? AND tanggal<? GROUP BY kategori ORDER BY total DESC');$q->execute($params);$kategoriPendapatan=$q->fetchAll();
$q=$pdo->prepare('SELECT kategori,SUM(jumlah) total,COUNT(*) jumlah_transaksi FROM pengeluaran WHERE tanggal>=? AND tanggal<? GROUP BY kategori ORDER BY total DESC');$q->execute($params);$kategoriPengeluaran=$q->fetchAll();
require '_header.php';
?>
<div class="page-heading"><div><h1>Laporan Keuangan</h1><p>Rekapitulasi bulanan, rincian transaksi, dan ringkasan kategori.</p></div><a class="btn-small" href="export-laporan.php?bulan=<?= $bulan ?>&tahun=<?= $tahun ?>">Unduh CSV</a></div>
<div class="content-panel"><form method="GET" class="filter-form"><div class="form-group"><label>Bulan</label><select name="bulan"><?php for($i=1;$i<=12;$i++): ?><option value="<?= $i ?>" <?= $bulan===$i?'selected':'' ?>><?= e(date('F',mktime(0,0,0,$i,1))) ?></option><?php endfor; ?></select></div><div class="form-group"><label>Tahun</label><input type="number" name="tahun" value="<?= $tahun ?>" min="2000" max="2100"></div><button class="btn-submit">Tampilkan Laporan</button></form></div>
<div class="dashboard-cards"><div class="dashboard-card"><div><p>Total Pendapatan</p><h2><?= rupiah($pendapatan) ?></h2></div></div><div class="dashboard-card"><div><p>Total Pengeluaran</p><h2><?= rupiah($pengeluaran) ?></h2></div></div><div class="dashboard-card"><div><p>Saldo Bersih</p><h2><?= rupiah($saldo) ?></h2></div></div></div>
<div class="dashboard-grid"><div class="content-panel"><div class="panel-heading"><h3>Pendapatan per Kategori</h3></div><div class="table-responsive"><table class="data-table"><thead><tr><th>Kategori</th><th>Transaksi</th><th>Total</th></tr></thead><tbody><?php foreach($kategoriPendapatan as $r): ?><tr><td><?= e($r['kategori']) ?></td><td><?= (int)$r['jumlah_transaksi'] ?></td><td><?= rupiah($r['total']) ?></td></tr><?php endforeach; ?><?php if(!$kategoriPendapatan): ?><tr><td colspan="3">Belum ada data.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="content-panel"><div class="panel-heading"><h3>Pengeluaran per Kategori</h3></div><div class="table-responsive"><table class="data-table"><thead><tr><th>Kategori</th><th>Transaksi</th><th>Total</th></tr></thead><tbody><?php foreach($kategoriPengeluaran as $r): ?><tr><td><?= e($r['kategori']) ?></td><td><?= (int)$r['jumlah_transaksi'] ?></td><td><?= rupiah($r['total']) ?></td></tr><?php endforeach; ?><?php if(!$kategoriPengeluaran): ?><tr><td colspan="3">Belum ada data.</td></tr><?php endif; ?></tbody></table></div></div></div>
<div class="content-panel"><div class="panel-heading"><h3>Rincian Pendapatan</h3></div><div class="table-responsive"><table class="data-table"><thead><tr><th>Kode</th><th>Tanggal</th><th>Kategori</th><th>Keterangan</th><th>Jumlah</th></tr></thead><tbody><?php foreach($dataPendapatan as $r): ?><tr><td><?= e($r['kode_transaksi']) ?></td><td><?= tanggal($r['tanggal']) ?></td><td><?= e($r['kategori']) ?></td><td><?= e($r['keterangan']) ?></td><td><?= rupiah($r['jumlah']) ?></td></tr><?php endforeach; ?><?php if(!$dataPendapatan): ?><tr><td colspan="5">Tidak ada transaksi pendapatan pada periode ini.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="content-panel"><div class="panel-heading"><h3>Rincian Pengeluaran</h3></div><div class="table-responsive"><table class="data-table"><thead><tr><th>Kode</th><th>Tanggal</th><th>Kategori</th><th>Keterangan</th><th>Jumlah</th></tr></thead><tbody><?php foreach($dataPengeluaran as $r): ?><tr><td><?= e($r['kode_transaksi']) ?></td><td><?= tanggal($r['tanggal']) ?></td><td><?= e($r['kategori']) ?></td><td><?= e($r['keterangan']) ?></td><td><?= rupiah($r['jumlah']) ?></td></tr><?php endforeach; ?><?php if(!$dataPengeluaran): ?><tr><td colspan="5">Tidak ada transaksi pengeluaran pada periode ini.</td></tr><?php endif; ?></tbody></table></div></div>
<?php require '_footer.php'; ?>
